const PUBLIC_HOME_HTML="<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>CIE Online Examination System</title><style>\n:root{--blue:#0b4da2;--navy:#082b57;--gold:#d9a52a;--light:#f5f8fc;--green:#168a55;--text:#172238;--muted:#68758a}*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;background:#f3f7fc;color:var(--text)}.wrap{max-width:1120px;margin:auto}.top{background:linear-gradient(135deg,var(--navy),var(--blue));color:#fff;padding:22px 18px 34px}.brand{display:flex;align-items:center;gap:14px}.logo{width:72px;height:72px;border-radius:50%;background:linear-gradient(145deg,#ffe697,#b97a05);display:grid;place-items:center;color:#0a356d;font-weight:900;font-size:23px;border:4px solid white}.brand h1{margin:0;font-size:clamp(24px,4vw,42px)}.brand p{margin:6px 0 0;opacity:.9}.hero{margin-top:24px;background:#fff;color:var(--text);border-radius:24px;padding:30px;display:grid;grid-template-columns:1.25fr .75fr;gap:24px;box-shadow:0 18px 45px rgba(0,0,0,.17)}.hero h2{margin:0 0 10px;font-size:clamp(28px,4vw,44px)}.hero p{font-size:17px;line-height:1.65;color:var(--muted)}.btn{display:inline-block;border:0;border-radius:12px;padding:14px 19px;font-weight:700;text-decoration:none;cursor:pointer}.green{background:var(--green);color:#fff}.blue{background:var(--blue);color:#fff}.cta{display:flex;gap:12px;flex-wrap:wrap;margin-top:20px}.mini{background:linear-gradient(160deg,#153f80,#071b37);border-radius:22px;padding:16px;color:white}.screen{background:#fff;color:var(--text);border-radius:15px;padding:16px}.test{border:1px solid #dde6f1;border-radius:12px;padding:12px;margin-top:11px}.badge{display:inline-block;background:#e9f7ef;color:#0e7445;border-radius:999px;padding:5px 9px;font-size:12px;font-weight:bold}section{padding:46px 18px}h3{font-size:30px;margin:0 0 18px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{background:#fff;border-radius:18px;padding:20px;box-shadow:0 7px 22px rgba(18,47,84,.08)}.promo{border-top:5px solid var(--gold)}.promo h4,.exam h4{font-size:20px;margin:8px 0}.promo p,.exam p{color:var(--muted);line-height:1.55}.download{background:linear-gradient(135deg,#0b4da2,#0a6cc8);color:#fff;border-radius:24px;padding:30px}.download p{opacity:.92}.note{font-size:13px;color:var(--muted)}footer{background:#071a35;color:#c9d6e8;padding:32px 18px}.foot{display:flex;justify-content:space-between;gap:20px;align-items:end;flex-wrap:wrap}.admin{font-size:13px;color:#98b0d2;text-decoration:none;border:1px solid #36577f;border-radius:9px;padding:9px 12px}.empty{color:var(--muted);background:#fff;border-radius:14px;padding:18px}.link{color:var(--blue);text-decoration:none;font-weight:700}@media(max-width:800px){.hero,.grid{grid-template-columns:1fr}.brand{align-items:flex-start}.logo{width:58px;height:58px;font-size:18px}}\n</style></head><body><div class=\"top\"><div class=\"wrap\"><div class=\"brand\"><div class=\"logo\">CIE</div><div><h1>CIE Online Examination System</h1><p>Career Institute of Education \u2022 Learn \u2022 Compete \u2022 Grow</p></div></div><div class=\"hero\"><div><span class=\"badge\">CIE EXAM PORTAL</span><h2>Give Exams. Check Results. Grow Smarter.</h2><p>Download the CIE Exam App, access multiple online tests, take timed examinations and review your performance.</p><div class=\"cta\"><a class=\"btn green\" href=\"/download-app\">\u2b07 Download CIE Exam App</a><a class=\"btn blue\" href=\"#upcoming-exams\">View Upcoming Exams</a></div><p class=\"note\">Latest Student App: V3.2.4 \u2022 Android APK</p></div><div class=\"mini\"><div class=\"screen\"><b>Available in CIE Exam App</b><div class=\"test\"><b>Multiple Exams</b><br><span class=\"badge\">Available</span></div><div class=\"test\"><b>Advanced Timers</b><p class=\"note\">Whole Paper \u2022 Per Question \u2022 Both</p></div><div class=\"test\"><b>Instant Result & Answer Review</b></div></div></div></div></div></div>\n<section><div class=\"wrap\"><h3>Promotions & Announcements</h3><div id=\"promos\" class=\"grid\"><div class=\"empty\">Loading promotions\u2026</div></div></div></section>\n<section id=\"upcoming-exams\" style=\"background:#f8fbff\"><div class=\"wrap\"><h3>Upcoming & Available Exams</h3><div id=\"exams\" class=\"grid\"><div class=\"empty\">Loading exams\u2026</div></div></div></section>\n<section><div class=\"wrap\"><div class=\"download\"><h3>Download CIE Exam App</h3><p>Use the latest Android app to register/login, view Tests, manage Profile and participate in CIE online exams.</p><a class=\"btn green\" href=\"/download-app\">\u2b07 Download Latest APK</a><p style=\"margin-bottom:0;font-size:13px\">If Android asks for permission, allow installation from your browser/file manager for this APK.</p></div></div></section>\n<section><div class=\"wrap\"><h3>How It Works</h3><div class=\"grid\"><div class=\"card\"><b>1. Download App</b><p>Install the latest CIE Exam App from this official exam portal.</p></div><div class=\"card\"><b>2. Login & Select Test</b><p>Login with your registered mobile number and PIN, then open Tests.</p></div><div class=\"card\"><b>3. Submit & Review</b><p>Complete the exam within its timer and view your result and answer review.</p></div></div></div></section>\n<footer><div class=\"wrap\"><div class=\"foot\"><div><b style=\"color:#fff\">Career Institute of Education (CIE)</b><div class=\"note\" style=\"color:#9db0ca;margin-top:7px\">Official Online Examination Portal \u2022 exam.cie.co.in</div></div><a class=\"admin\" href=\"/admin\">Admin Login</a></div></div></footer>\n<script>const esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));function fmt(v){if(!v)return'Anytime';try{return new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v))}catch{return v}}async function load(){try{const p=await fetch('/api/public/promotions').then(r=>r.json());document.getElementById('promos').innerHTML=p.length?p.map(x=>`<div class=\"card promo\"><span class=\"badge\">CIE</span><h4>${esc(x.title)}</h4><b>${esc(x.subtitle||'')}</b><p>${esc(x.details||'')}</p>${x.linkText&&x.linkUrl?`<a class=\"link\" href=\"${esc(x.linkUrl)}\">${esc(x.linkText)} \u2192</a>`:''}</div>`).join(''):'<div class=\"empty\">No current promotions.</div>'}catch{document.getElementById('promos').innerHTML='<div class=\"empty\">Promotions are temporarily unavailable.</div>'}try{const e=await fetch('/api/public/exams').then(r=>r.json());document.getElementById('exams').innerHTML=e.length?e.map(x=>`<div class=\"card exam\">${x.thumbnailUrl?`<img src=\"${esc(x.thumbnailUrl)}\" alt=\"${esc(x.name)}\" style=\"width:100%;height:150px;object-fit:cover;border-radius:12px;margin-bottom:12px\">`:``}<span class=\"badge\">${esc(String(x.status||'').toUpperCase())}</span><h4>${esc(x.name)}</h4><p>Start: ${esc(fmt(x.startAt))}<br>End: ${esc(x.endAt?fmt(x.endAt):'No fixed end time')}<br>${x.durationMinutes?`Whole Paper: ${x.durationMinutes} min<br>`:''}${x.perQuestionSeconds?`Per Question: ${x.perQuestionSeconds} sec<br>`:''}Passing: ${esc(x.passingPercentage)}%</p></div>`).join(''):'<div class=\"empty\">No active exams announced right now.</div>'}catch{document.getElementById('exams').innerHTML='<div class=\"empty\">Exam list is temporarily unavailable.</div>'}}load();</script></body></html>";
const ADMIN_LOGIN_HTML="<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>CIE Admin Login</title><style>body{margin:0;font-family:Arial;background:#f4f7fb;color:#172238}.box{max-width:430px;margin:70px auto;background:white;padding:28px;border-radius:18px;box-shadow:0 10px 32px #183b6b18}.logo{text-align:center;color:#0b4da2}label{display:block;margin-top:14px;font-weight:700}input{width:100%;box-sizing:border-box;padding:13px;border:1px solid #ccd7e5;border-radius:10px;margin-top:6px;font-size:16px}button{width:100%;padding:13px;border:0;border-radius:10px;background:#0b4da2;color:white;font-weight:700;margin-top:18px;cursor:pointer}.secondary{background:#5b6f87}.small{font-size:13px;color:#68758a;text-align:center;margin-top:14px}.link{color:#0b4da2;cursor:pointer;font-weight:700}.msg{margin-top:14px;padding:10px;border-radius:8px;background:#eef4fb;display:none}</style></head><body><div class=\"box\"><div class=\"logo\"><h1>CIE Admin Login</h1><p>Secure Exam Administration</p></div><div id=\"login\"><label>Admin ID<input id=\"adminId\" autocomplete=\"username\"></label><label>Password<input id=\"password\" type=\"password\" autocomplete=\"current-password\"></label><button id=\"loginBtn\">Login</button><div class=\"small\"><span class=\"link\" id=\"forgotLink\">Forgot Password?</span></div></div><div id=\"forgot\" style=\"display:none\"><h3>Forgot Password</h3><label>Admin ID<input id=\"fAdminId\"></label><label>Registered Email<input id=\"email\" type=\"email\"></label><button id=\"sendBtn\">Send Reset Link</button><button class=\"secondary\" id=\"backBtn\">Back to Login</button></div><div id=\"msg\" class=\"msg\"></div><div class=\"small\"><a href=\"/\" style=\"color:#0b4da2\">\u2190 Back to CIE Exam Portal</a></div></div><script>const $=x=>document.getElementById(x),msg=t=>{$('msg').textContent=t;$('msg').style.display='block'};$('loginBtn').onclick=async()=>{try{const r=await fetch('/api/admin/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({adminId:$('adminId').value,password:$('password').value})});const j=await r.json();if(!r.ok)throw Error(j.error);location.href='/admin'}catch(e){msg(e.message)}};$('forgotLink').onclick=()=>{$('login').style.display='none';$('forgot').style.display='block';$('fAdminId').value=$('adminId').value};$('backBtn').onclick=()=>{$('forgot').style.display='none';$('login').style.display='block'};$('sendBtn').onclick=async()=>{try{const r=await fetch('/api/admin/auth/forgot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({adminId:$('fAdminId').value,email:$('email').value})});const j=await r.json();if(!r.ok)throw Error(j.error);msg(j.message)}catch(e){msg(e.message)}};</script></body></html>";
const ADMIN_MEDIA_HTML="<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>CIE App & Exam Media</title><style>body{font-family:Arial;background:#f4f7fb;color:#172238;margin:0}.wrap{max-width:900px;margin:35px auto;padding:0 16px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px}.card{background:#fff;padding:22px;border-radius:16px;box-shadow:0 6px 22px #17365d18;margin:18px 0}label{display:block;font-weight:700;margin-top:12px}input,select,textarea,button{width:100%;box-sizing:border-box;padding:12px;margin-top:7px;border-radius:9px;border:1px solid #ccd7e5}button{border:0;background:#0b4da2;color:#fff;font-weight:700;cursor:pointer}.green{background:#168a55}.danger{background:#b3261e}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.msg{padding:10px;background:#eef4fb;border-radius:9px;margin-top:12px;display:none}.thumb{max-width:260px;max-height:150px;border-radius:10px;margin-top:10px}.small{font-size:13px;color:#68758a}a{color:#0b4da2;font-weight:700;text-decoration:none}@media(max-width:650px){.row{grid-template-columns:1fr}.top{display:block}}</style></head><body><div class=\"wrap\"><div class=\"top\"><div><h1>CIE App Management</h1><div class=\"small\">APK updates + Exam thumbnails</div></div><div><a href=\"/admin\">\u2190 Admin Portal</a></div></div><div class=\"card\"><h2>\ud83d\udcf1 Upload / Publish Android APK</h2><div id=\"current\" class=\"small\">Checking current published app\u2026</div><label>Version<input id=\"version\" placeholder=\"Example: V3.4\"></label><label>What's New / Update Notes<textarea id=\"notes\" rows=\"4\" placeholder=\"Write update details\"></textarea></label><label>Select APK<input id=\"apk\" type=\"file\" accept=\".apk,application/vnd.android.package-archive\"></label><button class=\"green\" id=\"uploadApk\">Upload & Publish APK</button><div id=\"apkMsg\" class=\"msg\"></div></div><div class=\"card\"><h2>\ud83d\uddbc Exam Thumbnail</h2><p class=\"small\">Create the exam normally, then select it here and upload its thumbnail. It will appear on the website and is also supplied to the Student App API.</p><label>Select Exam<select id=\"exam\"></select></label><div id=\"preview\"></div><label>Select Thumbnail<input id=\"thumb\" type=\"file\" accept=\"image/jpeg,image/png,image/webp\"></label><div class=\"row\"><button id=\"uploadThumb\">Upload / Replace Thumbnail</button><button class=\"danger\" id=\"removeThumb\">Remove Thumbnail</button></div><div id=\"thumbMsg\" class=\"msg\"></div></div></div><script>const $=x=>document.getElementById(x);function show(id,t){$(id).textContent=t;$(id).style.display='block'}async function loadApp(){try{const r=await fetch('/api/public/app-info'),j=await r.json();$('current').textContent=j.available?'Published: '+j.version+(j.notes?' \u2022 '+j.notes:''):'No APK published yet.'}catch{$('current').textContent='Could not load app status.'}}async function loadExams(){const r=await fetch('/api/admin/exams'),j=await r.json();$('exam').innerHTML=j.map(x=>'<option value=\"'+x.id+'\">'+String(x.name).replace(/</g,'&lt;')+'</option>').join('');preview()}function preview(){const id=$('exam').value;$('preview').innerHTML=id?'<img class=\"thumb\" src=\"/api/exams/'+id+'/thumbnail?t='+Date.now()+'\" onerror=\"this.remove()\">':''}$('exam').onchange=preview;$('uploadApk').onclick=async()=>{const f=$('apk').files[0],v=$('version').value.trim();if(!f||!v)return show('apkMsg','Version and APK are required.');const fd=new FormData();fd.append('apk',f);fd.append('version',v);fd.append('notes',$('notes').value);show('apkMsg','Uploading\u2026 please wait.');try{const r=await fetch('/api/admin/app-release',{method:'POST',body:fd}),j=await r.json();if(!r.ok)throw Error(j.error);show('apkMsg','APK uploaded and published successfully.');loadApp()}catch(e){show('apkMsg',e.message)}};$('uploadThumb').onclick=async()=>{const f=$('thumb').files[0],id=$('exam').value;if(!id||!f)return show('thumbMsg','Select exam and image.');const fd=new FormData();fd.append('thumbnail',f);try{const r=await fetch('/api/admin/exams/'+id+'/thumbnail',{method:'POST',body:fd}),j=await r.json();if(!r.ok)throw Error(j.error);show('thumbMsg','Thumbnail uploaded successfully.');preview()}catch(e){show('thumbMsg',e.message)}};$('removeThumb').onclick=async()=>{const id=$('exam').value;if(!id)return;try{const r=await fetch('/api/admin/exams/'+id+'/thumbnail',{method:'DELETE'}),j=await r.json();if(!r.ok)throw Error(j.error);show('thumbMsg','Thumbnail removed.');preview()}catch(e){show('thumbMsg',e.message)}};loadApp();loadExams();</script></body></html>";
const ADMIN_RESET_HTML="<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Reset CIE Admin Password</title><style>body{font-family:Arial;background:#f4f7fb}.box{max-width:430px;margin:80px auto;background:#fff;padding:28px;border-radius:18px}input,button{width:100%;box-sizing:border-box;padding:13px;margin-top:12px;border-radius:10px}input{border:1px solid #ccd7e5}button{border:0;background:#0b4da2;color:#fff;font-weight:bold}.msg{margin-top:14px}</style></head><body><div class=\"box\"><h2>Reset Admin Password</h2><p>Enter a new password of at least 8 characters.</p><input id=\"p1\" type=\"password\" placeholder=\"New Password\"><input id=\"p2\" type=\"password\" placeholder=\"Confirm New Password\"><button id=\"go\">Reset Password</button><div id=\"msg\" class=\"msg\"></div></div><script>document.getElementById('go').onclick=async()=>{const p1=document.getElementById('p1').value,p2=document.getElementById('p2').value,m=document.getElementById('msg');if(p1!==p2){m.textContent='Passwords do not match.';return}const token=new URLSearchParams(location.search).get('token')||'';try{const r=await fetch('/api/admin/auth/reset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,newPassword:p1})});const j=await r.json();if(!r.ok)throw Error(j.error);m.innerHTML='Password updated. <a href=\"/admin\">Login now</a>'}catch(e){m.textContent=e.message}};</script></body></html>";
app.get('/',(req,res)=>res.type('html').send(PUBLIC_HOME_HTML));
app.get('/admin',async(req,res)=>{if(!currentAdmin(req))return res.type('html').send(ADMIN_LOGIN_HTML);const f=path.join(__dirname,'admin','index.html');if(fs.existsSync(f)){let h=fs.readFileSync(f,'utf8');const b='<a href=\"/admin/media\" style=\"position:fixed;right:18px;bottom:18px;z-index:9999;background:#168a55;color:white;padding:12px 16px;border-radius:12px;text-decoration:none;font:bold 14px Arial;box-shadow:0 5px 18px #0003\">📱 App & Thumbnails</a>';h=h.includes('</body>')?h.replace('</body>',b+'</body>'):h+b;return res.type('html').send(h)}return res.status(503).send('<h2>Admin Portal file is not available yet.</h2>')});
app.get('/admin/login',(req,res)=>res.type('html').send(ADMIN_LOGIN_HTML));
app.get('/admin/reset',(req,res)=>res.type('html').send(ADMIN_RESET_HTML));
app.get('/admin/media',(req,res)=>{if(!currentAdmin(req))return res.redirect('/admin');res.type('html').send(ADMIN_MEDIA_HTML)});
app.get('/download-app',async(req,res)=>{try{if(useDb){const q=await pool.query('SELECT version,apk_data,apk_mime,file_name FROM app_releases WHERE published=true ORDER BY created_at DESC,id DESC LIMIT 1');if(q.rowCount){const x=q.rows[0];res.setHeader('Content-Type',x.apk_mime||'application/vnd.android.package-archive');res.setHeader('Content-Disposition','attachment; filename="'+String(x.file_name||'CIE_Online_Exam.apk').replace(/[\"\r\n]/g,'')+'"');return res.send(x.apk_data)}}const f=path.join(__dirname,'public','downloads','CIE_Online_Exam.apk');if(fs.existsSync(f))return res.download(f,'CIE_Online_Exam.apk');res.status(404).send('<h2>CIE Exam App APK is being updated.</h2><p>Please check again shortly.</p>')}catch(e){res.status(500).send('APK download temporarily unavailable.')}});
app.use(express.static(path.join(__dirname,'public'),{index:false}));

app.get('/api/public/app-info',async(req,res)=>{try{if(!useDb)return res.json({available:false});const q=await pool.query('SELECT version,notes,created_at AS "publishedAt" FROM app_releases WHERE published=true ORDER BY created_at DESC,id DESC LIMIT 1');res.json(q.rowCount?{available:true,...q.rows[0],downloadUrl:'/download-app'}:{available:false})}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/exams/:id/thumbnail',async(req,res)=>{try{if(!useDb||!/^\d+$/.test(req.params.id))return res.status(404).end();const q=await pool.query('SELECT thumbnail_data,thumbnail_mime FROM exams WHERE id=$1',[req.params.id]);if(!q.rowCount||!q.rows[0].thumbnail_data)return res.status(404).end();res.setHeader('Content-Type',q.rows[0].thumbnail_mime||'image/jpeg');res.setHeader('Cache-Control','public,max-age=300');res.send(q.rows[0].thumbnail_data)}catch(e){res.status(500).end()}});
app.get('/api/public/exams',async(req,res)=>{try{if(!useDb)return res.json([]);const q=await pool.query(`SELECT id,name,start_at AS "startAt",end_at AS "endAt",timer_mode AS "timerMode",duration_minutes AS "durationMinutes",per_question_seconds AS "perQuestionSeconds",question_limit AS "questionLimit",passing_percentage AS "passingPercentage",attempt_limit AS "attemptLimit",random_questions AS "randomQuestions",active,thumbnail_mime FROM exams WHERE active=true ORDER BY CASE WHEN start_at IS NULL THEN 1 ELSE 0 END,start_at ASC,id DESC LIMIT 12`);res.json(q.rows.map(x=>({...x,status:nowStatus(examPublic(x))})))}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/public/promotions',async(req,res)=>{try{if(!useDb)return res.json([]);const q=await pool.query('SELECT id,title,subtitle,details,link_text AS "linkText",link_url AS "linkUrl" FROM promotions WHERE active=true ORDER BY sort_order,id');res.json(q.rows)}catch(e){res.status(500).json({error:e.message})}});

app.post('/api/admin/auth/login',async(req,res)=>{try{if(!useDb)return res.status(503).json({error:'Database required.'});const adminId=norm(req.body?.adminId),password=String(req.body?.password||'');if(!adminId||!password)return res.status(400).json({error:'Enter Admin ID and Password.'});const q=await pool.query('SELECT admin_id,password_hash,active FROM admins WHERE admin_id=$1',[adminId]);if(!q.rowCount||!q.rows[0].active||!(await bcrypt.compare(password,q.rows[0].password_hash)))return res.status(401).json({error:'Admin ID or Password is incorrect.'});setAdminCookie(res,q.rows[0].admin_id);res.json({ok:true})}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/admin/auth/logout',(req,res)=>{clearAdminCookie(res);res.json({ok:true})});
app.get('/api/admin/auth/me',requireAdmin,async(req,res)=>{try{const q=await pool.query('SELECT admin_id AS "adminId",name,email FROM admins WHERE admin_id=$1',[req.admin.adminId]);res.json(q.rows[0]||{})}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/admin/auth/forgot',async(req,res)=>{try{if(!useDb)return res.status(503).json({error:'Database required.'});const adminId=norm(req.body?.adminId),email=norm(req.body?.email).toLowerCase();if(!adminId||!email)return res.status(400).json({error:'Enter Admin ID and registered Email.'});const q=await pool.query('SELECT admin_id,email FROM admins WHERE admin_id=$1 AND LOWER(email)=LOWER($2) AND active=true',[adminId,email]);if(!q.rowCount)return res.status(404).json({error:'Admin ID and Email do not match.'});const token=crypto.randomBytes(32).toString('hex'),hash=crypto.createHash('sha256').update(token).digest('hex');await pool.query('DELETE FROM admin_password_resets WHERE admin_id=$1 OR expires_at<NOW()',[adminId]);await pool.query("INSERT INTO admin_password_resets(admin_id,token_hash,expires_at) VALUES($1,$2,NOW()+INTERVAL '20 minutes')",[adminId,hash]);const resetUrl=`${req.protocol}://${req.get('host')}/admin/reset?token=${encodeURIComponent(token)}`;await sendAdminResetEmail(email,resetUrl);res.json({ok:true,message:'Password reset link sent to registered email.'})}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/admin/auth/reset',async(req,res)=>{try{const token=String(req.body?.token||''),newPassword=String(req.body?.newPassword||'');if(token.length<20||newPassword.length<8)return res.status(400).json({error:'Invalid reset link or password must be at least 8 characters.'});const hash=crypto.createHash('sha256').update(token).digest('hex');const q=await pool.query('SELECT id,admin_id FROM admin_password_resets WHERE token_hash=$1 AND used_at IS NULL AND expires_at>NOW()',[hash]);if(!q.rowCount)return res.status(400).json({error:'Reset link is invalid or expired.'});const ph=await bcrypt.hash(newPassword,12);const c=await pool.connect();try{await c.query('BEGIN');await c.query('UPDATE admins SET password_hash=$1,updated_at=NOW() WHERE admin_id=$2',[ph,q.rows[0].admin_id]);await c.query('UPDATE admin_password_resets SET used_at=NOW() WHERE id=$1',[q.rows[0].id]);await c.query('COMMIT')}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}res.json({ok:true,message:'Password updated. You can login now.'})}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/admin/auth/change-password',requireAdmin,async(req,res)=>{try{const oldPassword=String(req.body?.oldPassword||''),newPassword=String(req.body?.newPassword||'');if(newPassword.length<8)return res.status(400).json({error:'New password must be at least 8 characters.'});const q=await pool.query('SELECT password_hash FROM admins WHERE admin_id=$1',[req.admin.adminId]);if(!q.rowCount||!(await bcrypt.compare(oldPassword,q.rows[0].password_hash)))return res.status(401).json({error:'Current password is incorrect.'});const ph=await bcrypt.hash(newPassword,12);await pool.query('UPDATE admins SET password_hash=$1,updated_at=NOW() WHERE admin_id=$2',[ph,req.admin.adminId]);res.json({ok:true,message:'Password changed successfully.'})}catch(e){res.status(500).json({error:e.message})}});

// All admin data/actions below require a valid admin session.
app.use('/api/admin',(req,res,next)=>{if(req.path.startsWith('/auth/'))return next();return requireAdmin(req,res,next)});
app.use('/api/results',requireAdmin);
app.get('/api/health',(req,res)=>res.json({ok:true,mode:useDb?'postgres':'local-json',version:'3.3'}));

app.post('/api/register',async(req,res)=>{try{const b=req.body||{},name=norm(b.name),fatherName=norm(b.fatherName),mobile=norm(b.mobile),pin=String(b.pin||'');if(!validFullName(name))return res.status(400).json({error:'Enter full Student Name using letters only (at least 2 words).'});if(!validFullName(fatherName))return res.status(400).json({error:'Enter full Father Name using letters only (at least 2 words).'});if(!validMobile(mobile))return res.status(400).json({error:'Mobile Number must be exactly 10 digits.'});if(!validPin(pin))return res.status(400).json({error:'PIN must be exactly 4 digits.'});const pinHash=await bcrypt.hash(pin,10);if(useDb){const q=await pool.query('INSERT INTO students(name,father_name,mobile,pin_hash) VALUES($1,$2,$3,$4) ON CONFLICT(mobile) DO NOTHING RETURNING id,name,father_name,mobile,pin_hash',[name,fatherName,mobile,pinHash]);if(!q.rowCount)return res.status(409).json({error:'Mobile already registered. Please Login.'});return res.json({ok:true,student:studentPublic(q.rows[0])})}const s=readLocal('students.json');if(s.some(x=>String(x.mobile)===mobile))return res.status(409).json({error:'Mobile already registered. Please Login.'});const x={id:Date.now(),name,fatherName,mobile,pinHash,createdAt:new Date().toISOString()};s.push(x);writeLocal('students.json',s);res.json({ok:true,student:studentPublic(x)})}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/login',async(req,res)=>{try{const mobile=norm(req.body?.mobile),pin=String(req.body?.pin||'');if(!validMobile(mobile)||!validPin(pin))return res.status(400).json({error:'Enter 10-digit Mobile Number and 4-digit PIN.'});const s=await verifyStudent(mobile,pin);if(!s)return res.status(401).json({error:'Mobile Number or PIN is incorrect.'});res.json({ok:true,student:studentPublic(s)})}catch(e){res.status(500).json({error:e.message})}});
app.post('/api/forgot-pin',async(req,res)=>{try{const mobile=norm(req.body?.mobile);if(!validMobile(mobile))return res.status(400).json({error:'Enter a valid 10-digit Mobile Number.'});if(useDb){const s=await pool.query('SELECT id FROM students WHERE mobile=$1',[mobile]);if(!s.rowCount)return res.status(404).json({error:'Mobile Number is not registered.'});const p=await pool.query("SELECT id FROM pin_reset_requests WHERE mobile=$1 AND status='PENDING' LIMIT 1",[mobile]);if(!p.rowCount)await pool.query('INSERT INTO pin_reset_requests(student_id,mobile) VALUES($1,$2)',[s.rows[0].id,mobile]);return res.json({ok:true,message:'PIN reset request sent to Admin.'})}const students=readLocal('students.json'),s=students.find(x=>String(x.mobile)===mobile);if(!s)return res.status(404).json({error:'Mobile Number is not registered.'});const rr=readLocal('pin_reset_requests.json');if(!rr.some(x=>x.mobile===mobile&&x.status==='PENDING'))rr.push({id:Date.now(),studentId:s.id,mobile,status:'PENDING',requestedAt:new Date().toISOString()});writeLocal('pin_reset_requests.json',rr);res.json({ok:true,message:'PIN reset request sent to Admin.'})}catch(e){res.status(500).json({error:e.message})}});

app.post('/api/exams/available',async(req,res)=>{try{const student=await verifyStudent(norm(req.body?.mobile),String(req.body?.pin||''));if(!student)return res.status(401).json({error:'Invalid login.'});if(!useDb)return res.json([]);const q=await pool.query(`SELECT e.*,(SELECT COUNT(*)::int FROM questions q WHERE q.exam_id=e.id) question_count,(SELECT COUNT(*)::int FROM results r WHERE r.exam_id=e.id AND r.student_id=$1) attempts_used FROM exams e ORDER BY COALESCE(e.start_at,e.created_at) DESC,e.id DESC`,[student.id]);res.json(q.rows.map(r=>{const e=examPublic(r);return{...e,status:nowStatus(e),questionCount:Number(r.question_count),attemptsUsed:Number(r.attempts_used),attemptsRemaining:e.attemptLimit===0?null:Math.max(0,e.attemptLimit-Number(r.attempts_used))}}))}catch(e){res.status(500).json({error:e.message})}});

app.post('/api/exams/:id/start',async(req,res)=>{try{if(!useDb)return res.status(501).json({error:'V3.2 exam mode requires database.'});const student=await verifyStudent(norm(req.body?.mobile),String(req.body?.pin||''));if(!student)return res.status(401).json({error:'Invalid login.'});const id=String(req.params.id);if(!/^\d+$/.test(id))return res.status(400).json({error:'Invalid exam.'});const er=await pool.query('SELECT * FROM exams WHERE id=$1',[id]);if(!er.rowCount)return res.status(404).json({error:'Exam not found.'});const e=examPublic(er.rows[0]),st=nowStatus(e);if(st==='inactive')return res.status(403).json({error:'This exam is inactive.'});if(st==='upcoming')return res.status(403).json({error:'This exam has not started yet.'});if(st==='ended')return res.status(403).json({error:'This exam has ended.'});const used=Number((await pool.query('SELECT COUNT(*)::int c FROM results WHERE exam_id=$1 AND student_id=$2',[id,student.id])).rows[0].c);if(e.attemptLimit>0&&used>=e.attemptLimit)return res.status(403).json({error:'Your attempt limit for this exam is complete.'});let sql=`SELECT id,question,option_a AS a,option_b AS b,option_c AS c,option_d AS d,COALESCE(question_seconds,0) AS "questionSeconds" FROM questions WHERE exam_id=$1`;sql+=e.randomQuestions?' ORDER BY RANDOM()':' ORDER BY id';const params=[id];if(e.questionLimit>0){params.push(e.questionLimit);sql+=` LIMIT $${params.length}`}const qs=(await pool.query(sql,params)).rows;if(!qs.length)return res.status(400).json({error:'No questions uploaded for this exam.'});let expiresAt=null;const now=Date.now();if((e.timerMode==='whole'||e.timerMode==='both')&&e.durationMinutes>0)expiresAt=new Date(now+e.durationMinutes*60000);if(e.endAt){const end=new Date(e.endAt);if(!expiresAt||end<expiresAt)expiresAt=end}const token=randomToken();await pool.query('INSERT INTO exam_sessions(token,student_id,exam_id,expires_at,question_ids) VALUES($1,$2,$3,$4,$5::jsonb)',[token,student.id,id,expiresAt,JSON.stringify(qs.map(x=>Number(x.id)))]);res.json({sessionToken:token,exam:e,expiresAt:expiresAt?expiresAt.toISOString():null,questions:qs,attemptNumber:used+1})}catch(e){res.status(500).json({error:e.message})}});

app.post('/api/result',async(req,res)=>{try{const b=req.body||{},mobile=norm(b.mobile),pin=String(b.pin||''),student=await verifyStudent(mobile,pin);if(!student)return res.status(401).json({error:'Student login verification failed.'});if(useDb&&b.sessionToken){const sr=await pool.query(`SELECT s.*,e.name,e.passing_percentage,e.timer_mode,e.per_question_seconds FROM exam_sessions s JOIN exams e ON e.id=s.exam_id WHERE s.token=$1 AND s.student_id=$2`,[String(b.sessionToken),student.id]);if(!sr.rowCount)return res.status(400).json({error:'Invalid exam session.'});const ses=sr.rows[0];if(ses.submitted_at)return res.status(409).json({error:'This exam attempt is already submitted.'});const ids=Array.isArray(ses.question_ids)?ses.question_ids:JSON.parse(ses.question_ids||'[]');const submitted=Array.isArray(b.answers)?b.answers.map(v=>Number.isInteger(Number(v))?Number(v):-1):[];if(submitted.length!==ids.length)return res.status(400).json({error:'Answer count does not match this exam.'});const qr=await pool.query(`SELECT id,question,option_a AS a,option_b AS b,option_c AS c,option_d AS d,answer FROM questions WHERE id=ANY($1::bigint[])`,[ids]);const map=new Map(qr.rows.map(x=>[Number(x.id),x]));let score=0;const review=ids.map((qid,i)=>{const q=map.get(Number(qid));if(!q)return null;const si=submitted[i]>=0&&submitted[i]<=3?submitted[i]:-1,ci='ABCD'.indexOf(String(q.answer||'').toUpperCase());if(si===ci&&ci>=0)score++;return{question:q.question,a:q.a,b:q.b,c:q.c,d:q.d,selected:si>=0?'ABCD'[si]:'',correct:ci>=0?'ABCD'[ci]:'',isCorrect:si===ci&&ci>=0}}).filter(Boolean);const total=review.length,pct=total?+(score*100/total).toFixed(2):0,status=pct>=Number(ses.passing_percentage||40)?'PASS':'FAIL';const fatherName=student.father_name;const c=await pool.connect();try{await c.query('BEGIN');const r=await c.query(`INSERT INTO results(student_id,name,father_name,mobile,score,total,percentage,status,review_json,exam_id,exam_name) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9::jsonb,$10,$11) RETURNING id,student_id AS "studentId",name,father_name AS "fatherName",mobile,score,total,percentage,status,review_json AS review,exam_id AS "examId",exam_name AS "examName",created_at AS "createdAt"`,[student.id,student.name,fatherName,mobile,score,total,pct,status,JSON.stringify(review),ses.exam_id,ses.name]);await c.query('UPDATE exam_sessions SET submitted_at=NOW() WHERE id=$1',[ses.id]);await c.query('COMMIT');return res.json(r.rows[0])}catch(e){await c.query('ROLLBACK');throw e}finally{c.release()}}
// Compatibility for old V3.1 APK
let score=0,total=0,review=null;if(Array.isArray(b.answers)){const qs=useDb?(await pool.query('SELECT id,question,option_a AS a,option_b AS b,option_c AS c,option_d AS d,answer FROM questions ORDER BY id')).rows:readLocal('questions.json');const submitted=b.answers.map(v=>Number.isInteger(Number(v))?Number(v):-1);total=qs.length;review=qs.map((q,i)=>{const si=submitted[i]>=0&&submitted[i]<=3?submitted[i]:-1,ci='ABCD'.indexOf(String(q.answer||'').toUpperCase());if(si===ci&&ci>=0)score++;return{question:q.question,a:q.a,b:q.b,c:q.c,d:q.d,selected:si>=0?'ABCD'[si]:'',correct:ci>=0?'ABCD'[ci]:'',isCorrect:si===ci&&ci>=0}})}else{total=Math.max(0,Number(b.total)||0);score=Math.max(0,Number(b.score)||0)}const pct=total?+(score*100/total).toFixed(2):0,status=pct>=40?'PASS':'FAIL';if(useDb){const r=await pool.query(`INSERT INTO results(student_id,name,father_name,mobile,score,total,percentage,status,review_json,exam_name) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9::jsonb,'Legacy App Attempt') RETURNING id,score,total,percentage,status,review_json AS review,exam_name AS "examName",created_at AS "createdAt"`,[student.id,student.name,student.father_name,mobile,score,total,pct,status,review?JSON.stringify(review):null]);return res.json(r.rows[0])}res.status(501).json({error:'Local V3.2 result mode not supported.'})}catch(e){res.status(500).json({error:e.message})}});

